WITH cleaned AS (SELECT *, TO_DATE(reading_ts) AS reading_ts_date, pressure + temp_c AS pressure_plus_temp_c FROM device_readings WHERE reading_ts >= DATE '2025-09-01'), flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '30' MINUTE THEN 1 ELSE 0 END AS session_start_flag FROM cleaned), sessionized AS (SELECT id, device_code, reading_ts, temp_c, pressure, reading_ts_date, pressure_plus_temp_c, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT CASE WHEN pressure_plus_temp_c >= 82 THEN 'PREMIUM' ELSE 'STANDARD' END AS pressure_plus_temp_c_tier, DATE_TRUNC('MONTH', reading_ts_date) AS activity_month, DATE_TRUNC('WEEK', reading_ts_date) AS week_start, ROUND(AVG(pressure), 2) AS avg_pressure, COUNT(*) FILTER (WHERE device_code = 'DV-01') AS dv_01_rows, MIN(reading_ts) AS started_at, GROUPING(CASE WHEN pressure_plus_temp_c >= 82 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_id FROM sessionized GROUP BY GROUPING SETS ((CASE WHEN pressure_plus_temp_c >= 82 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('MONTH', reading_ts_date), DATE_TRUNC('WEEK', reading_ts_date)), (CASE WHEN pressure_plus_temp_c >= 82 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('MONTH', reading_ts_date)), ()) HAVING avg_pressure > 0
